    },
    {
      "indicator": "MM20",
      "reading": "38.7090",
      "interpretation": "Média curta. Está abaixo da MM50 — sinal de fraqueza de curto prazo; funciona como resistência dinâmica."
    },
    {
      "indicator": "MM50",
      "reading": "39.0308",
